#include &lt;iostream&gt;
using namespace std;

int main() {
    int num1, num2, resultado;
    char operador;

    cout &lt;&lt; "Ingrese el primer numero: ";
    cin &gt;&gt; num1;

    cout &lt;&lt; "Ingrese el segundo numero: ";
    cin &gt;&gt; num2;

    cout &lt;&lt; "Ingrese la operacion (+, -, *, /, %): ";
    cin &gt;&gt; operador;

    if (operador == '+') {
        resultado = num1 + num2;
        cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;

    } else if (operador == '-') {
        resultado = num1 - num2;
        cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;

    } else if (operador == '*') {
        resultado = num1 * num2;
        cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;

    } else if (operador == '/') {
        if (num2 == 0) {
            cout &lt;&lt; "Error: no se puede dividir entre cero." &lt;&lt; endl;
        } else {
            resultado = num1 / num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
        }

    } else if (operador == '%') {
        if (num2 == 0) {
            cout &lt;&lt; "Error: no se puede obtener residuo entre cero." 
                 &lt;&lt; endl;
        } else {
            resultado = num1 % num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
        }

    } else {
        cout &lt;&lt; "Operacion no valida." &lt;&lt; endl;
    }

    return 0;
}

