            break;

        case '*':
            resultado = num1 * num2;
            cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            break;

        case '/':
            if (num2 == 0) {
                cout &lt;&lt; "Error: no se puede dividir entre cero." 
                     &lt;&lt; endl;
            } else {
                resultado = num1 / num2;
                cout &lt;&lt; "Resultado: " &lt;&lt; resultado &lt;&lt; endl;
            }
            break;

        case '%':
            if (num2 == 0) {
                cout &lt;&lt; "Error: no se puede obtener residuo entre cero." 
                     &lt;&lt; endl;
