6.12 5. Programa completo
#include &lt;iostream&gt;
#include &lt;iomanip&gt;
using namespace std;

enum OpcionCajero {
    CONSULTAR_SALDO = 1,
    DEPOSITAR,
    RETIRAR,
    SALIR
};

int main() {
    double saldo = 1000.00;
    double monto;
    int opcion;

    cout &lt;&lt; fixed &lt;&lt; setprecision(2);

    do {
        cout &lt;&lt; "\n===== CAJERO AUTOMATICO =====" &lt;&lt; endl;
        cout &lt;&lt; "1. Consultar saldo" &lt;&lt; endl;
        cout &lt;&lt; "2. Depositar dinero" &lt;&lt; endl;
        cout &lt;&lt; "3. Retirar dinero" &lt;&lt; endl;
        cout &lt;&lt; "4. Salir" &lt;&lt; endl;
        cout &lt;&lt; "Seleccione una opcion: ";
        cin &gt;&gt; opcion;

        switch (opcion) {
            case CONSULTAR_SALDO:
                cout &lt;&lt; "Saldo disponible: Q" &lt;&lt; saldo &lt;&lt; endl;
                break;

            case DEPOSITAR:
                cout &lt;&lt; "Ingrese el monto a depositar: Q";
                cin &gt;&gt; monto;

                if (monto &gt; 0) {
                    saldo = saldo + monto;
                    cout &lt;&lt; "Deposito realizado correctamente." &lt;&lt; endl;
                    cout &lt;&lt; "Nuevo saldo: Q" &lt;&lt; saldo &lt;&lt; endl;
                } else {
                    cout &lt;&lt; "El monto debe ser mayor que cero." &lt;&lt; endl;
                }
                break;

            case RETIRAR:
                cout &lt;&lt; "Ingrese el monto a retirar: Q";
                cin &gt;&gt; monto;

                if (monto &lt;= 0) {
                    cout &lt;&lt; "El monto debe ser mayor que cero." &lt;&lt; endl;
                } else if (monto &gt; saldo) {
                    cout &lt;&lt; "Fondos insuficientes." &lt;&lt; endl;
                } else {
                    saldo = saldo - monto;
                    cout &lt;&lt; "Retiro realizado correctamente." &lt;&lt; endl;
                    cout &lt;&lt; "Nuevo saldo: Q" &lt;&lt; saldo &lt;&lt; endl;
                }
                break;

            case SALIR:
                cout &lt;&lt; "Gracias por utilizar el cajero automatico." &lt;&lt; endl;
                break;

            default:
                cout &lt;&lt; "Opcion no valida. Intente nuevamente." &lt;&lt; endl;
        }

    } while (opcion != SALIR);

    return 0;
}

