28.1 Promedio
double calcularPromedio(const vector&lt;int&gt;& notas)
{
    int suma = 0;

    for (int i = 0; i &lt; notas.size(); i++)
        suma = suma + notas[i];

    return suma / static_cast&lt;double&gt;(notas.size());
}

28.2 Mayor
int buscarMayor(const vector&lt;int&gt;& notas)
{
    int mayor = notas[0];

    for (int i = 1; i &lt; notas.size(); i++)
        if (notas[i] &gt; mayor)
            mayor = notas[i];

    return mayor;
}

28.3 Menor
int buscarMenor(const vector&lt;int&gt;& notas)
{
    int menor = notas[0];

    for (int i = 1; i &lt; notas.size(); i++)
        if (notas[i] &lt; menor)
            menor = notas[i];

    return menor;
}

